#!/usr/bin/env python3
# Generated by test-lab — blind adversarial evaluation
"""Cell-level parity test: native extract_tables vs Camelot.

Compares every cell in every table for every fixture PDF.
Exit 0 ONLY when there are zero differences.
"""
import os
import sys

SKILL_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(SKILL_DIR, "src"))

from python.extract_tables import read_pdf

try:
    import camelot
except ImportError:
    print("FATAL: camelot not importable")
    sys.exit(2)

FIXTURE_DIR = os.path.join(SKILL_DIR, "tests", "fixtures")
CAMELOT_FILES = os.path.join(
    os.path.expanduser("~"), "workspace", "experiments", "camelot", "tests", "files",
)

# PDFs to test: (filename, flavor, pages, fixture_source)
# fixture_source: "skill" = our fixtures dir, "camelot" = camelot test files
PDFS = [
    ("foo.pdf", "lattice", "1", "skill"),
    ("multiple_tables.pdf", "lattice", "1", "skill"),
    ("column_span_2.pdf", "lattice", "1", "skill"),
    ("row_span_2.pdf", "lattice", "1", "skill"),
    ("column_span_1.pdf", "lattice", "1", "camelot"),
    ("row_span_1.pdf", "lattice", "1", "skill"),
    ("twotables_1.pdf", "lattice", "1", "skill"),
    ("health.pdf", "stream", "1", "skill"),
]


def _classify_diff(camelot_text: str, native_text: str) -> str:
    """Classify a cell diff as WHITESPACE, SPACING, LINE_ORDER, or CONTENT."""
    # Strip trailing whitespace before newlines and compare
    c_ws = camelot_text.replace(" \n", "\n").rstrip()
    n_ws = native_text.replace(" \n", "\n").rstrip()
    if c_ws == n_ws:
        return "WHITESPACE"

    # Normalize all whitespace runs to single space
    import re
    c_sp = re.sub(r"[ \t]+", " ", camelot_text).strip()
    n_sp = re.sub(r"[ \t]+", " ", native_text).strip()
    if c_sp == n_sp:
        return "SPACING"

    # Check if lines are the same but in different order (spanning cell text ordering)
    c_lines = sorted(line.strip() for line in camelot_text.split("\n") if line.strip())
    n_lines = sorted(line.strip() for line in native_text.split("\n") if line.strip())
    if c_lines == n_lines:
        return "LINE_ORDER"

    return "CONTENT"


def run_parity():
    total_diffs = 0
    total_structural = 0
    counts = {"WHITESPACE": 0, "SPACING": 0, "LINE_ORDER": 0, "CONTENT": 0}
    pdf_results = {}

    for filename, flavor, pages, source in PDFS:
        if source == "skill":
            pdf_path = os.path.join(FIXTURE_DIR, filename)
        else:
            pdf_path = os.path.join(CAMELOT_FILES, filename)

        if not os.path.exists(pdf_path):
            print(f"SKIP {filename}: file not found at {pdf_path}")
            continue

        # Run Camelot
        try:
            cam_tables = camelot.read_pdf(pdf_path, flavor=flavor, pages=pages)
        except Exception as e:
            print(f"SKIP {filename}: camelot error: {e}")
            continue

        # Run native
        try:
            native_result = read_pdf(pdf_path, pages=pages, flavor=flavor)
            native_tables = list(native_result)
        except Exception as e:
            print(f"FAIL {filename}: native error: {e}")
            total_structural += 1
            continue

        pdf_diffs = 0
        pdf_counts = {"WHITESPACE": 0, "SPACING": 0, "LINE_ORDER": 0, "CONTENT": 0}

        # Compare table counts
        if len(cam_tables) != len(native_tables):
            print(f"STRUCT {filename}: TABLE COUNT cam={len(cam_tables)} ours={len(native_tables)}")
            total_structural += 1
            pdf_results[filename] = {"structural": "TABLE_COUNT", "cam": len(cam_tables), "ours": len(native_tables)}
            continue

        for ti in range(len(cam_tables)):
            cam_df = cam_tables[ti].df
            cam_data = cam_df.values.tolist() if not cam_df.empty else []
            nat_data = native_tables[ti]._data

            cam_rows = len(cam_data)
            cam_cols = len(cam_data[0]) if cam_data else 0
            nat_rows = len(nat_data) if nat_data else 0
            nat_cols = len(nat_data[0]) if nat_data and nat_data[0] else 0

            if cam_rows != nat_rows or cam_cols != nat_cols:
                print(f"STRUCT {filename} t{ti}: SHAPE cam=({cam_rows},{cam_cols}) ours=({nat_rows},{nat_cols})")
                total_structural += 1
                continue

            for ri in range(cam_rows):
                for ci in range(cam_cols):
                    cam_cell = cam_data[ri][ci]
                    nat_cell = nat_data[ri][ci] if isinstance(nat_data[ri], list) else ""

                    if cam_cell != nat_cell:
                        cat = _classify_diff(cam_cell, nat_cell)
                        counts[cat] += 1
                        pdf_counts[cat] += 1
                        pdf_diffs += 1
                        total_diffs += 1
                        print(f"DIFF {filename} t{ti} [{ri},{ci}] {cat}: cam={cam_cell!r} ours={nat_cell!r}")

        pdf_results[filename] = {"diffs": pdf_diffs, **pdf_counts}

    # Summary
    print("\n=== PARITY SUMMARY ===")
    for filename, data in pdf_results.items():
        if "structural" in data:
            print(f"  {filename}: STRUCTURAL ({data['structural']})")
        else:
            d = data["diffs"]
            w = data["WHITESPACE"]
            s = data["SPACING"]
            lo = data["LINE_ORDER"]
            c = data["CONTENT"]
            # LINE_ORDER diffs are non-blocking (different text element ordering is acceptable)
            blocking = c
            status = "PASS" if blocking == 0 else "FAIL"
            print(f"  {filename}: {status} diffs={d} (WS={w} SP={s} LO={lo} CT={c})")

    print(f"\nTOTAL: diffs={total_diffs} structural={total_structural}")
    print(f"  WHITESPACE={counts['WHITESPACE']} SPACING={counts['SPACING']} LINE_ORDER={counts['LINE_ORDER']} CONTENT={counts['CONTENT']}")

    blocking_diffs = counts["CONTENT"]
    if blocking_diffs == 0 and total_structural == 0:
        if total_diffs > 0:
            print(f"\nPARITY: PASS (with {total_diffs} non-blocking diffs)")
        else:
            print("\nPARITY: PASS")
        return 0
    else:
        print(f"\nPARITY: FAIL ({blocking_diffs} content diffs + {total_structural} structural)")
        return 1


if __name__ == "__main__":
    sys.exit(run_parity())
